        "example": "SELECT order_id, total_amount,\n       ROW_NUMBER() OVER (ORDER BY total_amount DESC) AS rn,\n       RANK() OVER (ORDER BY total_amount DESC) AS rnk,\n       DENSE_RANK() OVER (ORDER BY total_amount DESC) AS dense_rnk\nFROM orders;",
