    "solution": "BEGIN;\nUPDATE products SET price = 2600 WHERE product_id = 1;\nSAVEPOINT after_first_update;\nUPDATE products SET price = 999 WHERE product_id = 2;\nROLLBACK TO SAVEPOINT after_first_update;\nCOMMIT;",
